use vstd::prelude::*;

verus! {
    // Function to get the length of a vector
    fn vec_len<T>(x: &Vec<T>) -> (r: usize)
        requires
            x.len() > 0,
        ensures
            r == x.len(),
    {
        x.len() // Simply return the length of the vector
    }

    // Function to compute the logarithm base 10 of each element in the vector
    fn numpy_log10(x: Vec<f32>) -> (result: Vec<f32>)
        requires
            x.len() > 0,
        ensures
            result.len() == x.len(),
    {
        let mut result: Vec<f32> = Vec::new();
        let mut idx: usize = 0;

        while idx < x.len()
            invariant
                idx <= x.len(),
                result.len() == idx,
            decreases x.len() - idx,
        {
            // Push the log10 of the current element to the result vector
            result.push(x[idx].log10());
            idx = idx + 1;
        }
        result
    }
}

